from pathlib import Path
import sys


ROOT = Path.cwd()


def fail(message):
  print(message, file=sys.stderr)
  raise SystemExit(1)


expected_agents = (
  "# Agent instructions\n\n"
  "Do not edit this file. Run repository checks before reporting completion.\n"
)
if (ROOT / "AGENTS.md").read_text(encoding="utf-8") != expected_agents:
  fail("AGENTS.md changed")

documents = {
  path: (ROOT / path).read_text(encoding="utf-8")
  for path in (
    "README.md",
    "docs/concepts.md",
    "docs/cookbook.md",
    "docs/reference.md",
  )
}
combined = "\n".join(documents.values())

for required in (
  "lantern init",
  "lantern scan --format json",
  "LANTERN_CACHE_DIR",
  "schema version 3",
):
  if required.casefold() not in combined.casefold():
    fail(f"missing preserved fact: {required}")

if "## Getting started" not in documents["README.md"]:
  fail("README getting-started anchor was not preserved")
if "## Config file" not in documents["docs/reference.md"]:
  fail("reference config-file anchor was not preserved")

if "docs/concepts.md" not in documents["README.md"]:
  fail("landing page does not route to concepts")
if "docs/cookbook.md" not in documents["README.md"]:
  fail("landing page does not route to the cookbook")
if "docs/reference.md" not in documents["README.md"]:
  fail("landing page does not route to reference")

if documents["README.md"].casefold().count("schema version 3") > 0:
  fail("normative schema detail remains duplicated in the landing page")
if documents["docs/concepts.md"].casefold().count("lantern scan --format json") > 0:
  fail("task command remains duplicated in the conceptual guide")
if documents["docs/cookbook.md"].casefold().count("schema version 3") > 0:
  fail("normative schema detail remains duplicated in the cookbook")

concept_text = documents["docs/concepts.md"].casefold()
workspace_heading = concept_text.find("## workspace")
first_workspace_use = concept_text.find("workspace")
if workspace_heading < 0 or first_workspace_use != workspace_heading + 3:
  fail("workspace is used before its concept definition")
